import{RewardParticles}from'./systems/RewardParticles.js';import{AssetGallery}from'./builders/AssetGallery.js';import * as T from 'three';import{GraphicsEngine}from'./core/GraphicsEngine.js';import{InputController}from'./core/InputController.js';import{SoundSynthesizer}from'./core/SoundSynthesizer.js';import{SaveSystem}from'./core/SaveSystem.js';import{NetworkLAN}from'./core/NetworkLAN.js';import{RobloxAvatar}from'./builders/RobloxAvatar.js';import{PetFactory,PETS}from'./builders/PetFactory.js';import{block}from'./builders/VoxelAssetFactory.js';import{TreadmillSystem}from'./systems/TreadmillSystem.js';import{IncubatorSystem}from'./systems/IncubatorSystem.js';import{DualMergeMachine}from'./systems/DualMergeMachine.js';import{PetSanctuary}from'./systems/PetSanctuary.js';import{BossArenaSystem}from'./systems/BossArenaSystem.js';import{DadAdminPanel}from'./systems/DadAdminPanel.js';import{build as tycoon}from'./maps/Map1_MegaTycoon.js';import{build as obby}from'./maps/Map2_RainbowObby.js';import{build as city}from'./maps/Map3_PetCityCars.js';
class Game{constructor(){this.graphics=new GraphicsEngine();this.particles=new RewardParticles(this.graphics.scene);this.save=new SaveSystem();this.sound=new SoundSynthesizer();this.input=new InputController();this.network=new NetworkLAN(this);this.treadmill=new TreadmillSystem(this);this.incubator=new IncubatorSystem(this);this.merge=new DualMergeMachine(this);this.sanctuary=new PetSanctuary(this);this.boss=new BossArenaSystem(this);this.elapsed=0;this.velocity=0;this.map=0;this.checkpoint=new T.Vector3(0,0,10);this.avatar=new RobloxAvatar(this.save.data.avatar);this.player=this.avatar.group;this.graphics.scene.add(this.player);this.petMeshes=[];this.remotes=new Map();this.loadMap(0);this.syncPets();this.gallery=new AssetGallery(this.graphics.scene);new DadAdminPanel(this);document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{this.sound.unlock();this.loadMap(+b.dataset.map);document.querySelector('#launcher').hidden=true;this.sound.say('Vamos brincar!')});document.querySelector('#home').onclick=()=>document.querySelector('#launcher').hidden=false;document.querySelector('#calm').onclick=()=>{this.save.data.calm=!this.save.data.calm;this.sound.calm=this.save.data.calm;this.save.save();this.notify(this.save.data.calm?'🌙 Modo calmo':'☀️ Modo alegre')};document.querySelector('#host').onclick=()=>this.network.host();document.querySelector('#join').onclick=()=>this.network.join();document.querySelector('#emoji').onclick=()=>{this.network.socket?.emit('emoji');this.notify('❤️')};document.querySelector('#dress').onclick=()=>this.dress();document.querySelector('canvas').addEventListener('click',e=>{const ray=new T.Raycaster();ray.setFromCamera(new T.Vector2(e.clientX/innerWidth*2-1,1-e.clientY/innerHeight*2),this.graphics.camera);if(ray.intersectObjects(this.petMeshes,true).length){this.reward(2);this.sound.play('pet');this.notify('❤️ +2')}});this.graphics.camera.position.set(0,10,22);let last=null;const loop=now=>{const dt=last===null?0:Math.max(0,Math.min((now-last)/1000,.05));last=now;this.update(dt);requestAnimationFrame(loop)};requestAnimationFrame(loop);if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(console.warn)}notify(text){const el=document.querySelector('#toast');el.textContent=text;clearTimeout(this.messageTimer);this.messageTimer=setTimeout(()=>el.textContent='',1800)}reward(n){this.save.add(n);if(this.player)this.particles.emit(this.player.position,this.save.data.calm)}pay(n){if(this.save.spend(n))return true;this.notify('🪙 '+n+' → 🏃 Esteira');this.sound.say('Vamos correr na esteira para ganhar moedas');return false}panel(html){const p=document.querySelector('#panel');p.hidden=false;p.innerHTML=html+'<div><button id="close">✅ Voltar</button></div>';p.querySelector('#close').onclick=()=>p.hidden=true}dress(){this.panel('<h2>🎨 Seu boneco</h2><button id="color">🎨 Cor</button><button id="hat">🎩 Chapéu</button><button id="wing">🪽 Asas</button>');const a=this.save.data.avatar;for(const [id,fn]of [['color',()=>a.color=[0x368cfa,0xff91be,0x83dfb0,0xb59aff][Math.floor(Math.random()*4)]],['hat',()=>a.hat=(a.hat+1)%21],['wing',()=>a.wings=(a.wings+1)%11]])document.getElementById(id).onclick=()=>{fn();const pos=this.player.position.clone();this.graphics.scene.remove(this.player);this.avatar=new RobloxAvatar(a);this.player=this.avatar.group;this.player.position.copy(pos);this.graphics.scene.add(this.player);this.save.save()}}loadMap(id){if(this.world)this.graphics.scene.remove(this.world.root);this.map=id;this.driving=this.flying=false;this.cityCar=null;this.world=[tycoon,obby,city][id](this);this.graphics.scene.add(this.world.root);this.player.position.copy(this.world.spawn);this.checkpoint.copy(this.world.spawn);this.velocity=0;if(id===0)this.refreshHabitat();document.querySelector('#hint').textContent=['🏃 Esteira → 🥚 Ovos → 🧬 Fusão → 👑 Boss','🌈 Siga as estrelas • ⬆ Pular','🚙 Pise no botão do carro • 🐉 Voo mágico'][id]}refreshHabitat(){if(!this.habitatRoot||this.map!==0)return;this.habitatRoot.clear();for(let i=0;i<this.save.data.habitat;i++){const x=(i%5)*2-4,z=Math.floor(i/5)*3;block(this.habitatRoot,[0xf5c2d7,0xb5e3f7,0xffdc87][i%3],x,.6,z,1.6,1.2,1.6);const roof=block(this.habitatRoot,0xa297e1,x,1.5,z,1.9,.6,1.9);roof.rotation.z=.12}}syncPets(){this.petMeshes.forEach(p=>this.graphics.scene.remove(p));this.petMeshes=this.save.data.pets.slice(0,8).map(p=>{const m=PetFactory.create(p.id);this.graphics.scene.add(m);return m});document.querySelector('#pets').textContent=this.save.data.pets.slice(0,8).map(p=>PETS[p.id%40].icon).join(' ')}remoteMove(p){if(!this.remotes.has(p.id)){const a=new RobloxAvatar({color:0xe998c9});this.remotes.set(p.id,a);this.graphics.scene.add(a.group)}const a=this.remotes.get(p.id);a.group.visible=p.map===this.map;a.group.position.set(p.x,p.y,p.z);a.group.rotation.y=p.yaw;a.animate(this.elapsed,true)}removeRemote(id){const a=this.remotes.get(id);if(a)this.graphics.scene.remove(a.group);this.remotes.delete(id)}update(dt){this.elapsed+=dt;const p=this.player.position;const playing=document.querySelector('#launcher').hidden&&document.querySelector('#panel').hidden;const axis=playing?this.input.axis():{x:0,z:0};const length=Math.max(1,Math.hypot(axis.x,axis.z)),angle=this.input.look;const x=(axis.x*Math.cos(angle)+axis.z*Math.sin(angle))/length,z=(-axis.x*Math.sin(angle)+axis.z*Math.cos(angle))/length;const speed=this.driving?16:this.flying?12:6;const moving=Math.hypot(x,z)>.1;p.x+=x*speed*dt;p.z+=z*speed*dt;if(moving)this.player.rotation.y=Math.atan2(x,z);let floor=-100;for(const s of this.world.b.solids)if(Math.abs(p.x-s.x)<s.w/2+.25&&Math.abs(p.z-s.z)<s.d/2+.25&&p.y>=s.y-.35)floor=Math.max(floor,s.y);if(this.input.jump&&p.y<=floor+.08){this.velocity=8;this.sound.unlock();this.sound.play('jump')}this.input.jump=false;if(this.flying){p.y=3+Math.sin(this.elapsed)*.3;this.velocity=0}else{this.velocity-=18*dt;p.y+=this.velocity*dt;if(p.y<floor&&this.velocity<0){p.y=floor;this.velocity=0}}if(p.y<-12||Math.abs(p.x)>120||Math.abs(p.z)>150){p.copy(this.checkpoint);this.velocity=0;this.sound.play('boing')}if(this.cityCar){this.cityCar.visible=this.driving;if(this.driving){this.cityCar.position.copy(p);this.cityCar.rotation.y=this.player.rotation.y}}for(const pad of this.world.b.pads){pad.cool=Math.max(0,pad.cool-dt);const near=Math.hypot(p.x-pad.x,p.z-pad.z)<1.7;if(playing&&near&&!pad.cool){pad.cool=4;pad.fn()}}this.input.action=false;this.avatar.animate(this.elapsed,moving);this.petMeshes.forEach((m,i)=>{const target=new T.Vector3(p.x+Math.sin(i*2.4)*2.4,p.y+.2+Math.sin(this.elapsed*3+i)*.18,p.z-2-Math.floor(i/3)*1.2);m.position.lerp(target,1-Math.exp(-dt*5));m.rotation.y=this.player.rotation.y});if(playing){this.treadmill.update(dt);this.sanctuary.update(dt);this.boss.update(dt)}this.particles.update(dt);this.gallery?.update(dt);this.network.update(dt);const target=new T.Vector3(p.x+Math.sin(angle)*12,p.y+9,p.z+Math.cos(angle)*12);this.graphics.camera.position.lerp(target,1-Math.exp(-dt*5));this.graphics.camera.lookAt(p.x,p.y+1,p.z);document.querySelector('#coins').textContent='🪙 '+Math.floor(this.save.data.coins).toLocaleString('pt-BR');this.graphics.render(this.elapsed,this.save.data.calm)}}
try{window.caleb=new Game()}catch(e){console.error(e);document.querySelector('#toast').textContent='Não foi possível iniciar o 3D: '+e.message}
